  rollbackGuardianEvent: {
    parameters: {
      query?: never;
      header?: never;
      path: {
        eventId: number;
      };
      cookie?: never;
    };
    requestBody?: {
      content: {
        "application/json": {
          /** @description Override the value-moved-on guard (roll back even if the flag's value changed since the suspect change). */
          force?: boolean;
          /** @description Mandatory note if the scope requires one. */
          reason?: string;
        };
      };
    };
    responses: {
      /** @description Rolled back — the suspect flag's draft value restored and the event marked rolled_back. The served value is restored (and re-published for this environment only) when SDKs are still served the suspect change; `servedValueChanged` reports whether it was. */
      200: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          "application/json": components["schemas"]["GuardianRollbackResult"];
        };
      };
      /** @description A change note (reason) is required for this change. Also `bad_request` when the request carries a Confeature cookie and its body is not JSON. */
      400: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          "application/json": components["schemas"]["Error"];
        };
      };
      /** @description Missing or invalid credential. */
      401: {
        headers: {
          "WWW-Authenticate": components["headers"]["BasicChallenge"];
          [name: string]: unknown;
        };
        content: {
          "application/json": components["schemas"]["Error"];
        };
      };
      /** @description The token lacks guardian:write, or it is a management token without config:publish. Also `forbidden` (cross-origin request refused) when the request carries a Confeature cookie and comes from neither the dashboard's own origin nor an allowlisted one. */
      403: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          "application/json": components["schemas"]["Error"];
        };
      };
      /** @description Event not found / cross-org. */
      404: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          "application/json": components["schemas"]["Error"];
        };
      };
      /** @description The flag's value changed since the suspect (use force to override), or while the rollback was writing (nothing was rolled back; retry). */
      409: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          "application/json": components["schemas"]["GuardianValueChanged"];
        };
      };
      /** @description Rollback not available: the suspect is not a flag-value change, the same write also changed the flag's targeting rules (revert it through the v2 value API), or the value to restore is outside the setting's domain. */
      422: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          "application/json": components["schemas"]["Error"];
        };
      };
      429: components["responses"]["RateLimited"];
    };
  };
